"""Filesystem helpers: safe document paths and crash-safe atomic writes."""
import asyncio
import json
import os
import re
import tempfile
from typing import Any, Dict

from fastapi import HTTPException

# Document ids are generated by chunking.generate_doc_id() (12 hex chars).
# Legacy/test ids may be other short alphanumerics, but never contain separators or dots.
_DOC_ID_RE = re.compile(r"^[A-Za-z0-9_-]{1,64}$")


def is_valid_doc_id(doc_id: str) -> bool:
    return bool(doc_id) and bool(_DOC_ID_RE.match(doc_id))


def resolve_doc_dir(base_dir: str, doc_id: str) -> str:
    """
    Map a document id to its directory under `base_dir`.
    Rejects anything that could escape the data directory (../, absolute paths, encoded dots).
    """
    if not is_valid_doc_id(doc_id):
        raise HTTPException(status_code=404, detail="Document not found")
    base_real = os.path.realpath(base_dir)
    candidate = os.path.realpath(os.path.join(base_real, doc_id))
    if os.path.dirname(candidate) != base_real:
        raise HTTPException(status_code=404, detail="Document not found")
    return candidate


def _atomic_write(path: str, data: bytes) -> None:
    directory = os.path.dirname(path) or "."
    os.makedirs(directory, exist_ok=True)
    fd, tmp_path = tempfile.mkstemp(dir=directory, prefix=".tmp-", suffix=os.path.basename(path))
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(data)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp_path, path)
    except BaseException:
        try:
            os.unlink(tmp_path)
        except FileNotFoundError:
            pass
        raise


def atomic_write_bytes(path: str, data: bytes) -> None:
    _atomic_write(path, data)


def atomic_write_text(path: str, text: str) -> None:
    _atomic_write(path, text.encode("utf-8"))


def atomic_write_json(path: str, obj: Any) -> None:
    _atomic_write(path, json.dumps(obj, indent=2).encode("utf-8"))


_key_locks: Dict[str, asyncio.Lock] = {}


def key_lock(key: str) -> asyncio.Lock:
    """Per-key asyncio lock (e.g. one synthesis per audio file at a time)."""
    lock = _key_locks.get(key)
    if lock is None:
        lock = asyncio.Lock()
        _key_locks[key] = lock
        if len(_key_locks) > 4096:
            for k in [k for k, v in _key_locks.items() if not v.locked() and k != key][:2048]:
                _key_locks.pop(k, None)
    return lock
